import {
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
  PlaneGeometry,
  Mesh,
  Group,
  DirectionalLight,
  Vector3
} from 'three/webgpu';
import {
  uv,
  vec3,
  texture,
  uniform,
  mix
} from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  // 1. PALETTE & DESIGN TOKENS
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // 2. STAGE BACKDROP (Fills the required space, dark sophisticated gradient)
  const bgGeo = new PlaneGeometry(7.2, 5.5);
  const bgMat = new MeshBasicNodeMaterial();
  const baseColor = THREE.Color.NAMES ? new THREE.Color(colors.surface) : new THREE.Color(0x0b0b10);
  const bottomColor = THREE.Color.NAMES ? new THREE.Color(colors.ink) : new THREE.Color(0x16161d);

  bgMat.colorNode = mix(
    uniform(baseColor),
    uniform(bottomColor),
    uv().y
  );

  const bgMesh = new Mesh(bgGeo, bgMat);
  bgMesh.position.set(0, 0, -2.5);
  group.add(bgMesh);

  // 3. CONTACT LIGHTING FOR THE SYSTEM
  const keyLight = new DirectionalLight(colors.paper, 1.2);
  keyLight.position.set(2, 3, 4);
  group.add(keyLight);

  const rimLight = new DirectionalLight(colors.accent, 1.4);
  rimLight.position.set(-3, -2, 2);
  group.add(rimLight);

  // 4. MAIN DISPLACEMENT HERO CARD (Quote frame & Visual texture)
  // 64x64 tessellated plane as requested by parallax-plane specification
  const cardGeo = new PlaneGeometry(3.5, 2.2, 64, 64);
  const cardMat = new MeshStandardNodeMaterial({
    roughness: 0.55,
    metalness: 0.5,
    flatShading: false
  });

  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.position.set(0, 0, 0);
  group.add(cardMesh);

  // Load textures
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      cardMat.map = tex;
      cardMat.needsUpdate = true;
    });
  }

  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((depthTex) => {
      // TSL displacement logic
      const depthNode = texture(depthTex);
      cardMat.positionNode = positionNodeWithDisplacement(depthNode);
      cardMat.needsUpdate = true;
    });
  }

  function positionNodeWithDisplacement(depthTexNode) {
    const depthVal = depthTexNode.r;
    // Map depth value to subtle displacement along normal
    const displacementScale = uniform(0.18);
    const pos = uv();
    return vec3(
      pos.x.mul(3.5).sub(1.75),
      pos.y.mul(2.2).sub(1.1),
      depthVal.mul(displacementScale)
    );
  }

  // 5. HARDCODED/FALLBACK TEXT FOR THE ATELIER QUOTE
  // (Rendering quote directly as text overlay inside the active stage layout)
  const quoteGroup = new Group();
  quoteGroup.position.set(0, 0, 0.15); // Layered on top of plane

  const quoteText = ctx.fontAtlas.createText(
    "“PRECISION IS THE ULTIMATE LUXURY”", 
    { fontSize: 0.16, color: colors.paper, align: 'center' }
  );
  quoteText.position.set(0, 0.25, 0);
  quoteGroup.add(quoteText);

  const authorText = ctx.fontAtlas.createText(
    "NOVA ATELIER CHRONOMETRY", 
    { fontSize: 0.09, color: colors.accent, align: 'center', letterSpacingPx: 3 }
  );
  authorText.position.set(0, -0.25, 0);
  quoteGroup.add(authorText);

  group.add(quoteGroup);

  // 6. CINEMATIC PRIMITIVES
  const activePrimitives = [];
  const appliedParallax = ctx.primitives['parallax-scroll']?.(cardMesh, { intensity: 0.4 });
  if (appliedParallax) activePrimitives.push(appliedParallax);

  const appliedDepthRot = ctx.primitives['depth-rotate']?.(cardMesh, { maxDeg: 8 });
  if (appliedDepthRot) activePrimitives.push(appliedDepthRot);

  // Direct config primitives processing
  if (config.cinematicPrimitives) {
    for (const primitive of config.cinematicPrimitives) {
      if (primitive.name === 'parallax-scroll' || primitive.name === 'depth-rotate') continue; // Avoid double application
      const effect = ctx.primitives[primitive.name]?.(group, primitive.params);
      if (effect) activePrimitives.push(effect);
    }
  }

  // 7. BEHAVIOR & INTERACTION
  const timelines = [];

  // Hover: rise-in (subtle, 0.15 scene units) + dynamic reaction
  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(cardMesh.position, { z: 0.15, duration: 0.4, ease: 'power2.out' });
  hoverTl.to(quoteGroup.position, { z: 0.3, duration: 0.4, ease: 'power2.out' }, 0);

  group.userData.handlers = {
    pointerover: () => {
      hoverTl.play();
    },
    pointerout: () => {
      hoverTl.reverse();
    },
    click: () => {
      ctx.emit('hub-home.select', { node: config.id });
      // Settle click feedback
      gsap.fromTo(group.scale, 
        { x: 0.95, y: 0.95, z: 0.95 }, 
        { x: 1, y: 1, z: 1, duration: 0.6, ease: 'elastic.out(1, 0.5)' }
      );
    }
  };

  // 8. DISBURSE & CLEANUP
  group.userData.cleanup = () => {
    activePrimitives.forEach(p => p.cleanup?.());
    timelines.forEach(tl => tl.kill());
    hoverTl.kill();
    cardGeo.dispose();
    cardMat.dispose();
    bgGeo.dispose();
    bgMat.dispose();
  };

  return group;
}
